-- 诗人人生行旅图：poet.journey 为 JSON 数组，按时间序排列的落脚点。
-- 每点：place 古地名 / modern 今地名 / lon lat 经纬 / period 年代 / event 行止 / poems 该地所作诗（poem.id 数组）
ALTER TABLE poet ADD COLUMN journey MEDIUMTEXT NULL AFTER story_title;

UPDATE poet SET journey='[{"place": "浔阳柴桑", "modern": "江西九江西南", "lon": 115.89, "lat": 29.62, "period": "365—393 · 少年耕读", "event": "出身没落仕宦之家，少怀「猛志逸四海」；几度出仕，皆因亲老家贫、口腹自役。", "poems": []}, {"place": "江陵", "modern": "湖北荆州", "lon": 112.19, "lat": 30.33, "period": "398—401 · 幕府生涯", "event": "入桓玄幕府，看尽门阀倾轧、宦海浮沉，归意渐生。", "poems": []}, {"place": "彭泽", "modern": "江西彭泽", "lon": 116.55, "lat": 29.9, "period": "405 · 八十余日", "event": "为彭泽令，郡遣督邮至，吏白应束带见之；叹曰「吾不能为五斗米折腰，拳拳事乡里小人邪」，即日解印绶去职，赋《归去来兮辞》。", "poems": []}, {"place": "柴桑 · 归隐", "modern": "江西九江", "lon": 115.92, "lat": 29.58, "period": "405—427 · 采菊东篱", "event": "躬耕南山，把酒东篱，与庐山高僧往还，隐居终老。结庐人境，心远地偏，悠然见山。", "poems": [1, 2]}]' WHERE id=1;

UPDATE poet SET journey='[{"place": "绵州 · 青莲乡", "modern": "四川江油", "lon": 104.75, "lat": 31.77, "period": "701—724 · 蜀中", "event": "五岁诵六甲，十岁观百家；十五好剑术，二十五「仗剑去国，辞亲远游」。", "poems": []}, {"place": "扬州", "modern": "江苏扬州", "lon": 119.42, "lat": 32.39, "period": "726 · 二十六岁", "event": "漫游吴会，秋病卧扬州旅舍，客夜霜白，举头见月而成《静夜思》。", "poems": [3]}, {"place": "安陆", "modern": "湖北安陆", "lon": 113.69, "lat": 31.26, "period": "727—736", "event": "娶故相许圉师孙女，「酒隐安陆，蹉跎十年」。", "poems": []}, {"place": "长安", "modern": "陕西西安", "lon": 108.94, "lat": 34.27, "period": "742—744 · 翰林供奉", "event": "奉诏入京，供奉翰林；醉草诏书、力士脱靴，终为权贵所谗，赐金放还。花间一壶酒，对影成三人。", "poems": [5]}, {"place": "宣城", "modern": "安徽宣城", "lon": 118.76, "lat": 30.95, "period": "753—761 · 往来宣城", "event": "晚年屡游宣城，相看两不厌，只有敬亭山。", "poems": []}, {"place": "庐山", "modern": "江西庐山", "lon": 115.98, "lat": 29.56, "period": "756 · 屏风叠", "event": "初游庐山有「飞流直下三千尺」；是岁隐屏风叠，永王璘三聘入幕，由此罹祸。", "poems": [4]}, {"place": "白帝城", "modern": "重庆奉节", "lon": 109.58, "lat": 31.04, "period": "759 · 流放遇赦", "event": "坐永王案长流夜郎，溯江而上，行至白帝城遇赦——朝辞彩云间，千里江陵一日还。", "poems": [6]}, {"place": "当涂", "modern": "安徽当涂", "lon": 118.5, "lat": 31.57, "period": "762", "event": "投族叔当涂令李阳冰，枕上授简；病殁，传说醉中入水捉月骑鲸而去。", "poems": []}]' WHERE id=2;

UPDATE poet SET journey='[{"place": "蒲州", "modern": "山西永济", "lon": 110.28, "lat": 34.85, "period": "701—715", "event": "祖籍太原祁县，父迁蒲州；少年聪颖，通音律、善书画。", "poems": []}, {"place": "长安", "modern": "陕西西安", "lon": 108.94, "lat": 34.27, "period": "715—737 · 两京游历", "event": "十七岁独在异乡，重阳忆蒲州兄弟；二十一进士夺魁，为太乐丞，仕途几起几落。", "poems": [9, 10]}, {"place": "凉州", "modern": "甘肃武威", "lon": 102.64, "lat": 37.93, "period": "737 · 出塞", "event": "以监察御史出塞宣慰河西，大漠孤烟直，长河落日圆，诗境为之一阔。", "poems": []}, {"place": "辋川", "modern": "陕西蓝田", "lon": 108.92, "lat": 34.09, "period": "741—761 · 半官半隐", "event": "得宋之问蓝田别墅，与裴迪泛舟唱和，弹琴赋诗；安史乱后笃志奉佛，晚官尚书右丞，空山新雨、竹喧莲动皆成绝唱。", "poems": [7, 8]}]' WHERE id=3;

UPDATE poet SET journey='[{"place": "洛阳 · 巩县", "modern": "河南巩义", "lon": 113.02, "lat": 34.75, "period": "712—735", "event": "生于巩县瑶湾，七龄思即壮，开口咏凤凰。", "poems": []}, {"place": "长安", "modern": "陕西西安", "lon": 108.94, "lat": 34.27, "period": "746—755 · 困守十年", "event": "应诏就试，朝扣富儿门，暮随肥马尘；安史乱起身陷长安，国破山河在，感时花溅泪。", "poems": [11]}, {"place": "秦州", "modern": "甘肃天水", "lon": 105.72, "lat": 34.58, "period": "759 · 弃官西行", "event": "弃官携家流寓秦州，露从今夜白，月是故乡明。", "poems": [13]}, {"place": "成都", "modern": "四川成都", "lon": 104.07, "lat": 30.67, "period": "760—765 · 草堂", "event": "得故人严武相助，浣花溪畔筑草堂，暂得安顿；好雨知时节，随风潜入夜。", "poems": [12]}, {"place": "夔州", "modern": "重庆奉节", "lon": 109.46, "lat": 31.02, "period": "766—768", "event": "寓夔州两年，登白帝高台，无边落木萧萧下，不尽长江滚滚来。", "poems": [14]}, {"place": "岳阳", "modern": "湖南岳阳", "lon": 113.09, "lat": 29.36, "period": "768—770", "event": "漂泊湖湘，亲朋无一字，老病有孤舟；卒于潭岳间湘江舟中。", "poems": []}]' WHERE id=4;

UPDATE poet SET journey='[{"place": "新郑", "modern": "河南新郑", "lon": 113.74, "lat": 34.4, "period": "772—780", "event": "生于新郑东郭宅，兵乱早年随家迁避。", "poems": []}, {"place": "符离", "modern": "安徽宿州", "lon": 117.32, "lat": 33.66, "period": "782—799", "event": "避地符离，苦节读书——口舌成疮，手肘成胝。", "poems": []}, {"place": "长安", "modern": "陕西西安", "lon": 108.94, "lat": 34.27, "period": "787 · 行卷", "event": "十六岁以《赋得古原草送别》投谒顾况；况戏曰「长安米贵，居大不易」，及读「野火烧不尽」，叹曰「有句如此，居天下有甚难」。", "poems": [15]}, {"place": "江州", "modern": "江西九江", "lon": 115.99, "lat": 29.71, "period": "815—818 · 贬谪", "event": "武元衡案贬江州司马，浔阳江头夜送客，忽闻水上琵琶声——江州司马青衫湿。", "poems": []}, {"place": "杭州", "modern": "浙江杭州", "lon": 120.16, "lat": 30.25, "period": "822—824 · 刺杭州", "event": "赴杭道上吟「半江瑟瑟半江红」；守杭浚六井、筑堤蓄湖，最爱湖东行不足，绿杨阴里白沙堤。", "poems": [16, 17]}, {"place": "洛阳", "modern": "河南洛阳", "lon": 112.45, "lat": 34.62, "period": "829—846", "event": "晚居履道里，自号香山居士，与刘禹锡诗酒唱和，卒葬龙门香山。", "poems": []}]' WHERE id=5;

UPDATE poet SET journey='[{"place": "眉山", "modern": "四川眉山", "lon": 103.85, "lat": 30.05, "period": "1037—1056", "event": "眉州眉山人；程夫人授《范滂传》，慨然有澄清天下之志。", "poems": []}, {"place": "汴京", "modern": "河南开封", "lon": 114.31, "lat": 34.8, "period": "1057—1071", "event": "嘉祐二年进士，欧阳修见其书曰「吾当避此人出一头地」；与新党不合，自请外任。", "poems": []}, {"place": "杭州", "modern": "浙江杭州", "lon": 120.16, "lat": 30.25, "period": "1071—1074 通判 · 1089—1091 再知", "event": "初为杭州通判，「欲把西湖比西子，淡妆浓抹总相宜」；十八年后再知杭州，疏浚西湖、筑苏堤，三潭印月自此始。", "poems": [19], "lx": -25, "ly": 30}, {"place": "密州", "modern": "山东诸城", "lon": 119.41, "lat": 35.99, "period": "1074—1076 · 知州", "event": "知密州，西北望，射天狼；丙辰中秋欢饮达旦，怀子由而作水调歌头，明月几时有。", "poems": [18]}, {"place": "徐州", "modern": "江苏徐州", "lon": 117.18, "lat": 34.26, "period": "1077—1079", "event": "知徐州，黄河决口汇于城下，庐于城上，率军民抗洪七十余日。", "poems": []}, {"place": "湖州", "modern": "浙江湖州", "lon": 120.09, "lat": 30.87, "period": "1079 · 乌台诗案", "event": "知湖州三月，以诗文讪谤朝政下御史台狱，系狱百三十日，几死。", "poems": [], "ly": 22}, {"place": "黄州", "modern": "湖北黄冈", "lon": 114.87, "lat": 30.45, "period": "1080—1084 · 谪居", "event": "贬黄州团练副使，躬耕城东坡地，自号东坡居士；两赋一词，从此天下称苏东坡。", "poems": []}, {"place": "庐山", "modern": "江西庐山", "lon": 115.98, "lat": 29.56, "period": "1084 · 途经", "event": "量移汝州，道经庐山，横看成岭侧成峰，题诗西林寺壁。", "poems": [20]}, {"place": "惠州", "modern": "广东惠州", "lon": 114.42, "lat": 23.11, "period": "1094—1097", "event": "绍圣再贬惠州，日啖荔枝三百颗，不辞长作岭南人。", "poems": []}, {"place": "儋州", "modern": "海南儋州", "lon": 109.58, "lat": 19.52, "period": "1097—1100 · 天涯", "event": "责授琼州别驾、昌化军安置，渡海讲学明道；海南破天荒出进士，自公始。", "poems": []}, {"place": "常州", "modern": "江苏常州", "lon": 119.95, "lat": 31.78, "period": "1101", "event": "遇赦自海南北归，七月二十八日卒于常州；葬汝州郏城县，号小峨眉。", "poems": []}]' WHERE id=6;

UPDATE poet SET journey='[{"place": "济南 · 明水", "modern": "山东济南", "lon": 117.12, "lat": 36.65, "period": "1084—1101", "event": "生于齐州章丘明水，父李格非为苏门后四学士；少女时代溪亭日暮，沉醉不知归路。", "poems": [21]}, {"place": "汴京", "modern": "河南开封", "lon": 114.31, "lat": 34.8, "period": "1101—1127", "event": "与太学生赵明诚成婚，赌书泼茶，共撰《金石录》；书画词章，名动京师。", "poems": []}, {"place": "青州", "modern": "山东青州", "lon": 118.48, "lat": 36.69, "period": "1107—1127 · 归来堂", "event": "屏居青州乡里十年，易安室归来堂，节衣缩食以聚书，极文墨之乐。", "poems": []}, {"place": "江宁", "modern": "江苏南京", "lon": 118.8, "lat": 32.06, "period": "1128—1129", "event": "靖康之变，仓皇南渡；明诚知建康府，感怀京洛旧事，寻寻觅觅已自北地始。", "poems": []}, {"place": "金华", "modern": "浙江金华", "lon": 119.65, "lat": 29.08, "period": "1134", "event": "避乱金华，闻双溪春尚好——只恐双溪舴艋舟，载不动许多愁。", "poems": []}, {"place": "临安", "modern": "浙江杭州", "lon": 120.16, "lat": 30.25, "period": "1132—1155", "event": "流寓临安，物是人非事事休；晚境凄凉，改嫁离异、金石散尽，卒年不可考。", "poems": [22]}]' WHERE id=7;

UPDATE poet SET journey='[{"place": "济南 · 历城", "modern": "山东济南", "lon": 117.12, "lat": 36.65, "period": "1140—1161", "event": "生于金占区，祖父辛赞携以登高望远，指画山河；二十二岁聚众二千起义，率五十骑闯五万人金营，生擒叛将张安国。", "poems": []}, {"place": "临安", "modern": "浙江杭州", "lon": 120.16, "lat": 30.25, "period": "1162 · 献俘南归", "event": "押张安国献俘行在，脱身南归；「归正人」三字，自此伴其一生。", "poems": []}, {"place": "建康", "modern": "江苏南京", "lon": 118.8, "lat": 32.06, "period": "1168—1175", "event": "通判建康、参赞军务，楚天千里清秋，登赏心亭，把吴钩看了，栏杆拍遍。", "poems": []}, {"place": "带湖 · 上饶", "modern": "江西上饶", "lon": 117.97, "lat": 28.45, "period": "1182—1192 · 闲居", "event": "落职闲居带湖新居，醉里挑灯看剑，梦回吹角连营；夜行黄沙道中，听取蛙声一片。", "poems": [23, 24]}, {"place": "瓢泉 · 铅山", "modern": "江西铅山", "lon": 117.71, "lat": 28.32, "period": "1196—1207", "event": "再迁瓢泉，起用复罢者再；开禧北伐之际朝廷欲用，病笃辞免，九月十日忧愤而卒，临终大呼「杀贼」数声。", "poems": []}]' WHERE id=8;
